<section class="panel statement-panel"><div class="panel-head"><div><h3>Registros</h3><p>Mostrando até 300 movimentações</p></div></div><div class="table-wrap"><table><thead><tr><th>Data</th><th>Descrição</th><th>Categoria</th><th>Conta</th><th>Status</th><th class="right">Valor</th><th></th></tr></thead><tbody><?php foreach($transactions as $t): ?><tr><td><?=e(date('d/m/Y',strtotime($t['transaction_date'])))?></td><td><span class="transaction-name"><?=e($t['description'])?></span></td><td><?=e($t['category_name']??'—')?></td><td><?=e($t['account_name'])?></td><td><span class="status-pill <?=e($t['status'])?>"><?=match($t['status']){'paid'=>'Paga','received'=>'Recebida',default=>'Pendente'}?></span></td><td class="right <?= $t['type']==='income'?'amount-in':'amount-out' ?>"><?= $t['type']==='income'?'+':'−' ?><?=money((int)$t['amount'])?></td><td><div class="row-actions"><a href="/transactions?edit=<?=(int)$t['id']?>#transaction-form">Editar</a><form method="post" action="/transactions/cancel" onsubmit="return confirm('Cancelar esta movimentação? O registro será preservado no histórico.')"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$t['id']?>"><button>Cancelar</button></form></div></td></tr><?php endforeach; ?><?php if(!$transactions): ?><tr><td colspan="7" class="table-empty">Nenhuma movimentação encontrada. Cadastre sua primeira receita ou despesa abaixo.</td></tr><?php endif; ?></tbody></table></div></section>
<section class="panel editor-panel" id="transaction-form"><div class="panel-head"><div><h3><?=$edit?'Editar movimentação':'Adicionar movimentação'?></h3><p>Valores são armazenados em centavos para manter os cálculos precisos.</p></div></div><?php if(!$accounts): ?><div class="inline-note">Antes de registrar, <a href="/accounts">adicione uma conta financeira</a>.</div><?php else: ?><form method="post" action="/transactions/save" class="data-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><label>Tipo<select name="type" required><option value="expense" <?=($edit['type']??'expense')==='expense'?'selected':''?>>Despesa</option><option value="income" <?=($edit['type']??'')==='income'?'selected':''?>>Receita</option></select></label><label>Descrição<input name="description" maxlength="140" required value="<?=e($edit['description']??'')?>" placeholder="Ex.: Conta de luz"></label><label>Valor (R$)<input name="amount" inputmode="decimal" required value="<?=e(isset($edit['amount'])?money_input((int)$edit['amount']):'')?>" placeholder="0,00"></label><label>Data<input type="date" name="transaction_date" required value="<?=e($edit['transaction_date']??date('Y-m-d'))?>"></label><label>Conta<select name="account_id" required><?php foreach($accounts as $account): ?><option value="<?=(int)$account['id']?>" <?=($edit['account_id']??'')==$account['id']?'selected':''?>><?=e($account['name'])?></option><?php endforeach; ?></select></label><label>Categoria<select name="category_id"><option value="">Sem categoria</option><?php foreach($categories as $category): ?><option data-type="<?=e($category['type'])?>" value="<?=(int)$category['id']?>" <?=($edit['category_id']??'')==$category['id']?'selected':''?>><?=e($category['name'])?> · <?= $category['type']==='income'?'Receita':'Despesa' ?></option><?php endforeach; ?></select></label><label>Vencimento (opcional)<input type="date" name="due_date" value="<?=e($edit['due_date']??'')?>"></label><label>Status<select name="status"><option value="pending" <?=($edit['status']??'')==='pending'?'selected':''?>>Pendente</option><option value="paid" <?=($edit['status']??'')==='paid'?'selected':''?>>Paga</option><option value="received" <?=($edit['status']??'')==='received'?'selected':''?>>Recebida</option></select></label><label>Forma de pagamento<input name="payment_method" maxlength="40" value="<?=e($edit['payment_method']??'')?>" placeholder="Opcional"></label><label class="span-two">Observações<input name="notes" maxlength="500" value="<?=e($edit['notes']??'')?>" placeholder="Opcional"></label><div class="form-actions"><button class="button primary">Salvar movimentação</button><?php if($edit): ?><a class="button secondary" href="/transactions">Cancelar edição</a><?php endif; ?></div></form><?php endif; ?></section>
